#!/bin/sh
# Writes rcsdk_bearssl_names.h: every global symbol the vendored BearSSL
# defines, renamed with the prefix rcsdk_. Run it after updating BearSSL, from
# the repository root, with build trees (RCSDK_CRYPTO_BACKEND=bearssl) for
# arm64 and x86-64 (only the latter defines the AES-NI, PCLMUL and SSE2 code):
#   third_party/bearssl/rename-symbols.sh build/bearssl build/bearssl-x86_64
# NM may name an nm that reads all of their object formats (llvm-nm).
set -eu
nm=${NM:-nm}
out=third_party/bearssl/rcsdk_bearssl_names.h
# Mach-O prefixes every C symbol with an underscore; a tree where every
# symbol has one is Mach-O, and loses it.
symbols() {
    find "$1/third_party/CMakeFiles/rcsdk_bearssl.dir" \( -name '*.o' -o -name '*.obj' \) -exec "$nm" -g --defined-only {} + 2>/dev/null |
        awk 'NF == 3 { print $3 }' | grep -v -e '^\.' -e ':' | sort -u
}
names=$(for tree in "$@"; do
    list=$(symbols "$tree")
    if echo "$list" | grep -qv '^_'; then echo "$list"; else echo "$list" | sed -e 's/^_//'; fi
done | sed -e 's/^rcsdk_//' | sort -u) # Trees built with the header already have the prefix.
{
    echo '/* Every global symbol of the vendored BearSSL gets the prefix rcsdk_, so that'
    echo ' * a host linking its own BearSSL never clashes with the copy inside the SDK,'
    echo ' * static builds included (hidden visibility only applies to shared ones).'
    echo ' * Included first by every BearSSL source (third_party/CMakeLists.txt) and by'
    echo ' * the SDK code that calls BearSSL. Generated by rename-symbols.sh. */'
    echo '#ifndef RCSDK_BEARSSL_NAMES_H'
    echo '#define RCSDK_BEARSSL_NAMES_H'
    for name in $names; do
        echo "#define $name rcsdk_$name"
    done
    echo '#endif'
} > "$out"
echo "$out: $(echo "$names" | wc -l | tr -d ' ') symbols"
